#ifndef TOUCH_FILTER_H
#define TOUCH_FILTER_H

#include <stdint.h>

/* -----------------------------------------------------------------------
 * touch_filter.h
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29 Oct 2026 for Tony's display/UI subsystem (best-ui).
 * BJT2 Sound Modulating Toy — Touch Press Filter (one press = one tap)
 * Subsystem: Display/UI (Tony). Generative AI was used to assist.
 *
 * The firmware samples the resistive panel once per touch scan (40 ms):
 * two reads of X, then two of Y. This module decides what each sample
 * means and turns all the samples of one finger press into one tap:
 *   touch_classify()       one sample -> PRESSED, RELEASED or UNSURE
 *   touch_filter_update()  a press -> one TAP, then HELD while it lasts
 *
 * Why: one bad sample used to end the press. A light or rolling finger
 * gives an inconsistent or out-of-range sample now and then, and the next
 * good sample, 40 ms later, was then a second tap at the same spot, on
 * the screen the first tap had just opened. Several Home tiles lie over a
 * button of the screen they open (Record over Start Recording, Play over
 * the play button, Effects over the effect rows, Volume over + and mute).
 * Now a press ends only after TOUCH_RELEASE_SAMPLES released samples, and
 * an unsure sample neither starts nor ends one.
 *
 * "In range" is touch_is_pressed() (touch_calibration.c). No HAL calls:
 * the glue (tony_ui.c) reads the ADC and passes the counts in.
 * ----------------------------------------------------------------------- */

/* Two reads of one axis further apart than this (ADC counts): the finger
 * moved, or pressed too lightly, during the sample. The same limit the
 * firmware used before this module. */
#define TOUCH_SPREAD_MAX        150U

/* RELEASED samples that end a press, counted since its last PRESSED
 * sample (UNSURE samples in between do not reset the count). At one
 * sample per 40 ms the finger is off the glass for about 80 ms. */
#define TOUCH_RELEASE_SAMPLES   2U

typedef enum {
    TOUCH_SAMPLE_RELEASED = 0,  /* Neither pair in range: no finger        */
    TOUCH_SAMPLE_PRESSED,       /* Both pairs in range, reads agree        */
    TOUCH_SAMPLE_UNSURE         /* Anything else                           */
} touch_sample_t;

typedef enum {
    TOUCH_ACT_NONE = 0,         /* Nothing to do                           */
    TOUCH_ACT_TAP,              /* First PRESSED sample of a press         */
    TOUCH_ACT_HELD              /* A later PRESSED sample of that press    */
} touch_action_t;

typedef struct {
    uint8_t down;               /* 1 from the tap until the press ends     */
    uint8_t released;           /* RELEASED samples since the last PRESSED */
} touch_filter_t;

/**
 * touch_classify
 * One sample of the panel, as two (x, y) pairs: (x1, y1) and (x2, y2).
 * A pair is in range when touch_is_pressed() accepts both its values
 * (TOUCH_NO_PRESS_THRESHOLD_LOW..HIGH, ui_types.h).
 *   PRESSED   both pairs in range, |x1 - x2| <= TOUCH_SPREAD_MAX and
 *             |y1 - y2| <= TOUCH_SPREAD_MAX
 *   RELEASED  neither pair in range
 *   UNSURE    anything else: only one pair in range, or both in range
 *             but further apart than TOUCH_SPREAD_MAX
 *
 * @return  TOUCH_SAMPLE_PRESSED, TOUCH_SAMPLE_RELEASED or
 *          TOUCH_SAMPLE_UNSURE.
 */
touch_sample_t touch_classify(uint16_t x1, uint16_t y1,
                              uint16_t x2, uint16_t y2);

/**
 * touch_filter_init
 * No finger down. A zero-initialised static touch_filter_t is the same
 * thing. NULL is ignored.
 *
 * @param f  Filter state.
 */
void touch_filter_init(touch_filter_t *f);

/**
 * touch_filter_update
 * Feed one classified sample, once per touch scan:
 *   PRESSED while up    -> TOUCH_ACT_TAP; the press is down now
 *   PRESSED while down  -> TOUCH_ACT_HELD (Volume +/- repeats on these)
 *   RELEASED while down -> TOUCH_ACT_NONE; the TOUCH_RELEASE_SAMPLES-th
 *                          RELEASED sample since the last PRESSED one
 *                          ends the press
 *   UNSURE, RELEASED while up, or an unknown value -> TOUCH_ACT_NONE,
 *                          nothing changes
 * So a press gives one tap however many bad samples it has, and HELD
 * only ever comes on a PRESSED sample.
 *
 * @param f       Filter state. NULL -> TOUCH_ACT_NONE.
 * @param sample  touch_classify()'s verdict on this sample.
 * @return        TOUCH_ACT_TAP, TOUCH_ACT_HELD or TOUCH_ACT_NONE.
 */
touch_action_t touch_filter_update(touch_filter_t *f, touch_sample_t sample);

#endif /* TOUCH_FILTER_H */
